def get_disease_info(disease_name: str) -> dict:
    """
    Safely retrieve metadata for a given disease name.
    Returns a default fallback dictionary if the disease is not found,
    so the app never crashes due to a missing lookup.
    """
    return DISEASE_INFO.get(disease_name, {
        "description": "Detailed information is not available for this condition.",
        "causes": ["Not available"],
        "precautions": ["Please consult a certified medical professional."],
        "lifestyle_tips": ["Maintain a healthy diet and lifestyle."],
        "diet": ["Follow a balanced, doctor-recommended diet."],
        "exercise": ["Follow doctor-recommended activity levels."],
        "when_to_consult": "Please consult a certified medical professional for guidance.",
        "specialist": "General Physician",
        "base_risk": "Medium",
    })
